import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;","reason":"Import AndroidKeyStore APIs and their checked-exception types for persistent current wrapping-key lookup and first-use generation." ,"symbol":"MasterKey imports"},{"source_file_path":"mobile/src/main/java/org/fedorahosted/freeotp/encryptor/MasterKey.java","original_code":"    private static final int ITERATIONS = 100000;
    private static final int BYTES = 32;

    private final EncryptedKey mEncryptedKey;
    private final String mAlgorithm;
    private final int mIterations;
    private final byte[] mSalt;","edit_kind":"constant","corrected_code":"    private static final int ITERATIONS = 100000;
    private static final int BYTES = 32;
    private static final String ANDROID_KEY_STORE = "AndroidKeyStore";
    private static final String CURRENT_WRAPPING_KEY_ALIAS = "currentMasterKey";

    private final EncryptedKey mEncryptedKey;
    private final String mAlgorithm;
    private final int mIterations;
    private final byte[] mSalt;","reason":"Define the persistent AndroidKeyStore provider and current wrapping-key identity shared with the coordinated current-record lifecycle.","symbol":"MasterKey current wrapping-key constants"},{"source_file_path":"mobile/src/main/java/org/fedorahosted/freeotp/encryptor/MasterKey.java","original_code":"    private static SecretKeyFactory getSecretKeyFactory() throws NoSuchAlgorithmException {
        try {
            return SecretKeyFactory.getInstance("PBKDF2withHmacSHA512");
        } catch (NoSuchAlgorithmException e) {
            return SecretKeyFactory.getInstance("PBKDF2withHmacSHA1");
        }
    }","edit_kind":"method","corrected_code":"    private static SecretKeyFactory getSecretKeyFactory() throws NoSuchAlgorithmException {
        try {
            return SecretKeyFactory.getInstance("PBKDF2withHmacSHA512");
        } catch (NoSuchAlgorithmException e) {
            return SecretKeyFactory.getInstance("PBKDF2withHmacSHA1");
        }
    }

    private static KeyStore getAndroidKeyStore() throws NoSuchAlgorithmException,
            InvalidKeyException, IOException {
        try {
            KeyStore keyStore = KeyStore.getInstance(ANDROID_KEY_STORE);
            keyStore.load(null);
            return keyStore;
        } catch (KeyStoreException | CertificateException e) {
            throw new InvalidKeyException("Unable to load the current wrapping key store", e);
        }
    }

    private static SecretKey getStoredCurrentWrappingKey(KeyStore keyStore)
            throws NoSuchAlgorithmException, InvalidKeyException {
        try {
            return (SecretKey) keyStore.getKey(CURRENT_WRAPPING_KEY_ALIAS, null);
        } catch (KeyStoreException | UnrecoverableKeyException e) {
            throw new InvalidKeyException("Unable to read the current wrapping key", e);
        }
    }

    private static SecretKey getCurrentWrappingKey(String wrappingKeyId)
            throws NoSuchAlgorithmException, InvalidKeyException, IOException {
        if (!CURRENT_WRAPPING_KEY_ALIAS.equals(wrappingKeyId)) {
            throw new InvalidKeyException("Unknown current wrapping key: " + wrappingKeyId);
        }

        SecretKey key = getStoredCurrentWrappingKey(getAndroidKeyStore());
        if (key == null) {
            throw new InvalidKeyException("Current wrapping key is unavailable");
        }
        return key;
    }

    private static SecretKey getOrCreateCurrentWrappingKey() throws NoSuchAlgorithmException,
            InvalidKeyException, IOException {
        SecretKey existing = getStoredCurrentWrappingKey(getAndroidKeyStore());
        if (existing != null) {
            return existing;
        }

        try {
            KeyGenerator keyGenerator = KeyGenerator.getInstance(
                    KeyProperties.KEY_ALGORITHM_AES, ANDROID_KEY_STORE);
            keyGenerator.init(new KeyGenParameterSpec.Builder(CURRENT_WRAPPING_KEY_ALIAS,
                    KeyProperties.PURPOSE_ENCRYPT | KeyProperties.PURPOSE_DECRYPT)
                    .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                    .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                    .build());
            return keyGenerator.generateKey();
        } catch (InvalidAlgorithmParameterException | NoSuchProviderException e) {
            throw new InvalidKeyException("Unable to create the current wrapping key", e);
        }
    }","reason":"Add persistent AndroidKeyStore-backed current-key resolution. Current-record reads resolve only the identity stored in the record and fail if unavailable; first-use generation is restricted to new-record writes.","symbol":"MasterKey current wrapping-key resolution"},{"source_file_path":"mobile/src/main/java/org/fedorahosted/freeotp/encryptor/MasterKey.java","original_code":"    private MasterKey(PBEKeySpec spec) throws NoSuchAlgorithmException,
            IllegalBlockSizeException, InvalidKeyException, BadPaddingException,
            NoSuchPaddingException, InvalidKeySpecException, IOException {
        SecretKeyFactory skf = getSecretKeyFactory();
        SecretKey pwd = skf.generateSecret(spec);

        byte[] raw = new byte[pwd.getEncoded().length];
        new SecureRandom().nextBytes(raw);
        SecretKey key = new SecretKeySpec(raw, "AES");

        mEncryptedKey = EncryptedKey.encrypt(pwd, key);
        mIterations = spec.getIterationCount();
        mAlgorithm = skf.getAlgorithm();
        mSalt = spec.getSalt();
    }","edit_kind":"method","corrected_code":"    private MasterKey(PBEKeySpec spec) throws NoSuchAlgorithmException,
            IllegalBlockSizeException, InvalidKeyException, BadPaddingException,
            NoSuchPaddingException, InvalidKeySpecException, IOException {
        SecretKeyFactory skf = getSecretKeyFactory();
        SecretKey legacyKey = skf.generateSecret(spec);

        byte[] raw = new byte[legacyKey.getEncoded().length];
        new SecureRandom().nextBytes(raw);
        SecretKey key = new SecretKeySpec(raw, "AES");

        mEncryptedKey = EncryptedKey.encrypt(getOrCreateCurrentWrappingKey(), key,
                CURRENT_WRAPPING_KEY_ALIAS);
        mIterations = spec.getIterationCount();
        mAlgorithm = skf.getAlgorithm();
        mSalt = spec.getSalt();
    }","reason":"Route newly generated MasterKey records through the coordinated current EncryptedKey overload and generated persistent wrapping key rather than using the PBKDF2-derived value as a current encryption key.","symbol":"MasterKey constructor"},{"source_file_path":"mobile/src/main/java/org/fedorahosted/freeotp/encryptor/MasterKey.java","original_code":"    private SecretKey decrypt(PBEKeySpec spec) throws NoSuchAlgorithmException,
            InvalidKeySpecException, IllegalBlockSizeException, InvalidKeyException,
            BadPaddingException, InvalidAlgorithmParameterException, NoSuchPaddingException,
            IOException {
        SecretKeyFactory skf = SecretKeyFactory.getInstance(mAlgorithm);
        SecretKey pwd = skf.generateSecret(spec);
        return mEncryptedKey.decrypt(pwd);
    }","edit_kind":"method","corrected_code":"    private SecretKey decrypt(PBEKeySpec spec) throws NoSuchAlgorithmException,
            InvalidKeySpecException, IllegalBlockSizeException, InvalidKeyException,
            BadPaddingException, InvalidAlgorithmParameterException, NoSuchPaddingException,
            IOException {
        SecretKeyFactory skf = SecretKeyFactory.getInstance(mAlgorithm);
        SecretKey legacyKey = skf.generateSecret(spec);
        if (mEncryptedKey.isCurrentRecord()) {
            return mEncryptedKey.decrypt(legacyKey,
                    getCurrentWrappingKey(mEncryptedKey.getWrappingKeyId()));
        }
        return mEncryptedKey.decrypt(legacyKey);
    }","reason":"Retain the PBKDF2-derived key for legacy records, while current records select their persistent generated wrapping key by the stored record identity and use the coordinated dual-key decrypt contract.","symbol":"MasterKey decrypt(PBEKeySpec)"}],"manual_review_required":true,"provided_contracts":["MasterKey.generate(String) and MasterKey.decrypt(String) retain their existing public signatures and checked-exception contracts.","New MasterKey records are created through EncryptedKey.encrypt(SecretKey, SecretKey, String) using the persistent current wrapping-key identity currentMasterKey.","MasterKey retains PBKDF2-derived key resolution for records without the current discriminator and uses EncryptedKey.isCurrentRecord(), getWrappingKeyId(), and dual-key decrypt for current records.","Current AndroidKeyStore key reads do not generate a replacement key when decrypting a current record whose key is unavailable."],"required_contracts":["EncryptedKey must provide isCurrentRecord(), getWrappingKeyId(), decrypt(SecretKey legacyKey, SecretKey currentKey), and encrypt(SecretKey wrappingKey, SecretKey plaintext, String wrappingKeyId) with the coordinated current/legacy behavior.","Encryptor must use the same currentMasterKey AndroidKeyStore alias and compatible AES/GCM key-generation parameters for new records.","The coordinated instrumentation test must cover current MasterKey round trips and retained legacy two-argument EncryptedKey record decryption."],"source_file_path":"mobile/src/main/java/org/fedorahosted/freeotp/encryptor/MasterKey.java","required_tests":["Verify a newly generated MasterKey decrypts correctly using the persistent current AndroidKeyStore wrapping key.","Verify a legacy EncryptedKey record remains decryptable with the PBKDF2-derived legacy key and stored legacy parameters.","Verify current-record key lookup uses the record wrapping-key identity and fails rather than replacing a missing current key."]}
